void CWGroupList::SetWire(ANTDEF *p)
{
	int i, j;

	Delete();
	ap = p;
	wmax = p->wmax;
	memcpy(wdef, p->wdef, wmax * sizeof(WDEF));
	for( i = 0; i < wmax; i++ ){
		wdef[i].PNo = 1;
		if( Con[i]==0xff ){
			Con[i] = BYTE(gmax);
			Connect(gmax, wdef[i].X1, wdef[i].Y1, wdef[i].Z1);
			Connect(gmax, wdef[i].X2, wdef[i].Y2, wdef[i].Z2);
			gmax++;
		}
	}
	for( i = 0; i < gmax; i++ ){
		List[i].Init(wdef);
		for( j = 0; j < wmax; j++ ){
			if( Con[j] == BYTE(i) ){
				List[i].AddWire(j);
			}
		}
		List[i].AnaWire();
	}
	Sort();
}

void CWGroupList::Update(void)
{
	int		i, j;
	int		n;

	int DelFlag = 0;
	for( i = 0; i < wmax; i++ ){		// 歯抜けをサーチ
		if( !wdef[i].PNo ){
			DelFlag = 1;
			break;
		}
	}
	WREF	*rp;
	double	B = List[BaseW].GetX();
	double	bx = 0.0;
	for( i = BaseW, n = 0; i >= 0; i-- ){
		bx -= Intval[i];
		for( rp = List[i].pB, j = 0; j < List[i].bcnt; j++, rp++ ){
			if( rp->wp->PNo ){
				if( !DelFlag ) n = rp->ref;
				memcpy(&ap->wdef[n], rp->wp, sizeof(WDEF));
				ap->wdef[n].X1 += bx + B;
				ap->wdef[n].X2 += bx + B;
				n++;
			}
		}
	}
	bx = 0.0;
	for( i = BaseW + 1; i < gmax; i++ ){
		bx += Intval[i];
		for( rp = List[i].pB, j = 0; j < List[i].bcnt; j++, rp++ ){
			if( rp->wp->PNo ){
				if( !DelFlag ) n = rp->ref;
				memcpy(&ap->wdef[n], rp->wp, sizeof(WDEF));
				ap->wdef[n].X1 += bx + B;
				ap->wdef[n].X2 += bx + B;
				n++;
			}
		}
	}
	ap->wmax = DelFlag ? n : wmax;
}

void CWGroupList::CreateWire(int w, int type)
{
	int wm;
	if( w ){
		List[w].Init(wdef);
		for( int i = 0; i < List[w-1].bcnt; i++ ){
			wm = GetNewWire();
			memcpy(&wdef[wm], List[w-1].pB[i].wp, sizeof(WDEF));
			List[w].AddWire(wm);
		}
		List[w].AnaWire();
		if( Intval[w-1] ){
			Intval[w] = Intval[w-1];
		}
		else if( (w >= 2) && Intval[w-2] ){
			Intval[w] = Intval[w-2];
		}
		else {
			Intval[w] = exeenv.rmd/6;
		}
		gmax++;
	}
	else {
		SetNewType(w, type);
	}
}

void CWGroupList::InsertItem(int w)
{
	if( w < gmax ){
		int i;
		for( i = gmax;i > w; i-- ){
			memcpy(&List[i], &List[i-1], sizeof(CWGroup));
			memcpy(&Intval[i], &Intval[i-1], sizeof(double));
		}
		List[w].Clear();
		int wm;
		List[w].Init(wdef);
		for( i = 0; i < List[w+1].bcnt; i++ ){
			wm = GetNewWire();
			memcpy(&wdef[wm], List[w+1].pB[i].wp, sizeof(WDEF));
			List[w].AddWire(wm);
		}
		List[w].AnaWire();
		if( Intval[w+1] ){
			Intval[w] = Intval[w+1];
		}
		else if( w && Intval[w-1] ){
			Intval[w] = Intval[w-1];
		}
		else {
			Intval[w] = exeenv.rmd/6;
		}
		gmax++;
		if( w <= BaseW ) BaseW++;
	}
	else {
		CreateWire(w, cwHDP);
	}
}

void CWGroupList::DeleteItem(int n)
{
	if( n >= gmax ) return;
	DeleteWire(n);
	// テーブルから削除
	int i;
	for( i = n; i < (gmax - 1); i++ ){
		memcpy(&List[i], &List[i+1], sizeof(CWGroup));
		memcpy(&Intval[i], &Intval[i+1], sizeof(double));
	}
	List[i].Clear();
	gmax--;
	if( n <= BaseW ) BaseW--;
}

void CWGroupList::DeleteWire(int n)
{
	if( n >= gmax ) return;
	// 関連ワイヤを削除
	int i;
	for( i = 0; i < List[n].bcnt; i++ ){
		List[n].pB[i].wp->PNo = 0;
	}
	List[n].Delete();
}

void CWGroupList::SetNewType(int n, int type)
{
	if( n > gmax ) return;
	int		wm;
	double	rmd = exeenv.rmd;
	if( !rmd ) rmd = 23.0;
	double	Z = 0.0;
	double	Round = rmd;
	double	Width = rmd/2;
	double	Height = rmd/2;
	double	Rad = 0.005;
	if( n < gmax ){
		if( type == List[n].Type ) return;	// 同一タイプ
		Z = List[n].BZ;
		Round = List[n].GetRound();
		Width = List[n].GetWidth();
		Height = List[n].GetHeight();
		Rad = List[n].GetR();
	}
	if( n < gmax ) DeleteWire(n);
	switch(type){
		case cwHDP: // 水平DP
			List[n].Init(wdef);
			wm = AddWire(0, -1.0, 0, 0, 1.0, 0, Rad, 0);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetWidth(Round ? (Round/2.0) : Width ? Width : Height ? Height : rmd/2);
			break;
		case cwVDP:	// 垂直DP
			List[n].Init(wdef);
			wm = AddWire(0, 0, -1.0, 0, 0, 1.0, Rad, 0);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetHeight(Round ? (Round/2.0) : Width ? Width : Height ? Height : rmd/2);
			break;
		case cwVSQ:	// 垂直□
			List[n].Init(wdef);
			wm = AddWire(0, -1, -1, 0, 1, -1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 1, -1, 0, 1, 1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 1, 1, 0, -1, 1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -1, 1, 0, -1, -1, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
		case cwVDM:	// 垂直◇
			List[n].Init(wdef);
			wm = AddWire(0, 1, 0, 0, 0, -1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, -1, 0, -1, 0, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -1, 0, 0, 0, 1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, 1, 0, 1, 0, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
		case cwVTA:	// 垂直△
			List[n].Init(wdef);
			wm = AddWire(0, COS30, -0.5, 0, -COS30, -0.5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -COS30, -0.5, 0, 0, 1.0, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, 1.0, 0, COS30, -0.5, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
		case cwVITA:// 垂直▽
			List[n].Init(wdef);
			wm = AddWire(0, COS30, 0.5, 0, -COS30, 0.5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -COS30, 0.5, 0, 0, -1.0, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, -1.0, 0, COS30, 0.5, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
		case cwVPIE:	// 垂直○
			List[n].Init(wdef);
			wm = AddWire(0, SIN22R5, -COS22R5, 0, -SIN22R5, -COS22R5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -SIN22R5, -COS22R5, 0, -COS22R5, -SIN22R5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -COS22R5, -SIN22R5, 0, -COS22R5, SIN22R5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -COS22R5, SIN22R5, 0, -SIN22R5, COS22R5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -SIN22R5, COS22R5, 0, SIN22R5, COS22R5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, SIN22R5, COS22R5, 0, COS22R5, SIN22R5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, COS22R5, SIN22R5, 0, COS22R5, -SIN22R5, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, COS22R5, -SIN22R5, 0, SIN22R5, -COS22R5, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
		case cwVSQ2:	// 垂直双□
			List[n].Init(wdef);
			wm = AddWire(0, -2, 1, 0, 0, 1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, 1, 0, 2, 1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 2, 1, 0, 2, -1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 2, -1, 0, 0, -1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, -1, 0, -2, -1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -2, -1, 0, -2, 1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, 1, 0, 0, -1, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
#define	_KVSQ2	1.5
			List[n].SetRound(Round ? (Round*_KVSQ2) : Width ? (Width * _KVSQ2*2) : Height ? (Height * _KVSQ2*2) : (rmd * _KVSQ2));
			break;
		case cwVTA2:	// 垂直双▽
			List[n].Init(wdef);
			wm = AddWire(0, -2, 1, 0, 0, 0.01, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, 0.01, 0, 2, 1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 2, 1, 0, 2, -1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 2, -1, 0, 0, -0.01, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, -0.01, 0, -2, -1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, -2, -1, 0, -2, 1, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 0, 0.01, 0, 0, -0.01, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
#define	_KVTA2	0.71
			Round = Round ? (Round*_KVTA2) : Width ? (Width*_KVTA2*2.0) : Height ? (Height*_KVTA2*2.0) : (rmd*_KVTA2*2.0);
			List[n].SetWidth(Round);
			List[n].SetHeight(Round/2);
			break;
		case cwHSQ:	// 水平□
			List[n].Init(wdef);
			wm = AddWire(-1, -1, Z, 1, -1, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(1, -1, Z, 1, 1, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(1, 1, Z, -1, 1, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(-1, 1, Z, -1, -1, Z, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
		case cwHDM:	// 水平◇
			List[n].Init(wdef);
			wm = AddWire(0, -1, Z, -1, 0, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(-1, 0, Z, 0, 1, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0, 1, Z, 1, 0, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(1, 0, Z, 0, -1, Z, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
		case cwHTA:	// 水平△
			List[n].Init(wdef);
			wm = AddWire(0.5, COS30, Z, 0.5, -COS30, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(0.5, -COS30, Z, -1.0, 0, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(-1.0, 0, Z, 0.5, COS30, Z, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
		case cwHITA:// 水平▽
			List[n].Init(wdef);
			wm = AddWire(-0.5, COS30, Z, -0.5, -COS30, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(-0.5, -COS30, Z, 1.0, 0, Z, Rad, -1);
			List[n].AddWire(wm);
			wm = AddWire(1.0, 0, Z, -0.5, COS30, Z, Rad, -1);
			List[n].AddWire(wm);
			List[n].AnaWire();
			List[n].SetRound(Round ? Round : Width ? Width * 2.0 : Height ? Height * 2.0 : rmd);
			break;
	}
	if( n >= gmax ) gmax++;
}
///----------------------------------------------------------------
/// ワイヤ番号からエレメント番号を得る
int CWGroupList::GetEleNo(int w)
{
	WREF *rp;
	int i, n;

	for( i = 0; i < gmax; i++ ){
		for(rp = List[i].pB, n = List[i].bcnt; n; n--, rp++ ){
			if( rp->ref == w ) return i;
		}
	}
	return -1;
}
///----------------------------------------------------------------
/// ワイヤからグループポインタを得る
CWGroup* CWGroupList::GetCW(int w)
{
	int e;

	if( (e = GetEleNo(w))!=-1 ){
		return &List[e];
	}
	else {
		return NULL;
	}
}
///----------------------------------------------------------------
/// ワイヤ番号からX軸絶対位置を得る
double CWGroupList::GetXAbs(int w)
{
	int e;

	if( (e = GetEleNo(w))!=-1 ){
		return GetXPosition(e) + List[0].GetX();
	}
	else {
		return 0.0;
	}
}
